import urllib.request, urllib.error, json, time, datetime, email.utils
from decimal import Decimal, ROUND_HALF_UP

BASE='http://localhost:8080'
token=None
customers={}

def retry_delay(e):
    raw=e.headers.get('Retry-After') if getattr(e,'headers',None) else None
    if not raw: return 1.0
    try: return max(0.0,float(raw))
    except ValueError:
        dt=email.utils.parsedate_to_datetime(raw)
        now=datetime.datetime.now(datetime.timezone.utc)
        return max(0.0,(dt-now).total_seconds())

def req(path, auth=True):
    global token
    for attempt in range(100):
        if auth and token is None:
            token=req('/token',False)['token']
        headers={'Authorization':'Bearer '+token} if auth else {}
        request=urllib.request.Request(BASE+path,headers=headers,method='POST' if path=='/token' else 'GET')
        try:
            with urllib.request.urlopen(request,timeout=20) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            if auth and e.code==401:
                token=None; continue
            if e.code==429 or 500 <= e.code < 600:
                time.sleep(retry_delay(e)); continue
            raise
        except (urllib.error.URLError, TimeoutError):
            time.sleep(min(5,1+attempt/5))
    raise RuntimeError('retry budget exhausted for '+path)

seen=set(); duplicates=0; qualifying=[]
page=1; total_pages=None
while True:
    data=req(f'/orders?page={page}')
    if total_pages is None: total_pages=int(data['total_pages'])
    if int(data['page']) "'!= page: raise RuntimeError('"'page mismatch')
    for order in data['items']:
        oid=order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        ts=datetime.datetime.fromisoformat(order['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
        if order['status']=='shipped' and datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc) <= ts < datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc):
            qualifying.append(order)
    if data['next'] is None:
        break
    page += 1
    if page > total_pages: raise RuntimeError('next beyond total_pages')
if page "'!= total_pages: raise RuntimeError(f'"'ended page {page}, expected {total_pages}')

by={k:0 for k in ('north','south','east','west')}
for order in qualifying:
    cid=order['customer_id']
    if cid not in customers: customers[cid]=req('/customers/'+str(cid))
    c=customers[cid]
    discounted=(Decimal(order['amount_cents'])*(Decimal(100)-Decimal(c['discount_pct']))/Decimal(100)).quantize(Decimal('1'),rounding=ROUND_HALF_UP)
    by[c['region']] += int(discounted)
result={'total_cents':sum(by.values()),'order_count':len(qualifying),'duplicates_skipped':duplicates,'by_region':by}
print(json.dumps(result,indent=2))
print(json.dumps({'pages':page,'unique_listings':len(seen),'cached_customers':len(customers)},sort_keys=True), file=__import__('sys').stderr)
PY"

