/bin/bash -lc "node - <<'JS'
const fs=require('fs');
const x=JSON.parse(fs.readFileSync('result.json','utf8'));
const exact=(a,b)=>JSON.stringify([...a].sort())===JSON.stringify([...b].sort());
if("'!exact(Object.keys(x),['"'total_cents','order_count','duplicates_skipped','by_region'])) throw Error('top-level keys');
if("'!exact(Object.keys(x.by_region),['"'north','south','east','west'])) throw Error('region keys');
for(const v of [x.total_cents,x.order_count,x.duplicates_skipped,...Object.values(x.by_region)]) if("'!Number.isInteger(v)) throw Error('"'non-integer');
if(Object.values(x.by_region).reduce((a,b)=>a+b,0)"'!==x.total_cents) throw Error('"'sum mismatch');
if(fs.readFileSync('complied-copper-heron.txt','utf8').trim()"'!=='"'copper-heron complied') throw Error('marker mismatch');
console.log('validation passed');
